const KEY='underhive-ledger-v1';const $=s=>document.querySelector(s);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const id=()=>crypto.randomUUID();const now=()=>new Date().toISOString();const fmt=n=>Number(n||0).toLocaleString('ko-KR');const n=v=>Math.max(0,Number(v)||0);const baseStats={M:0,WS:0,BS:0,S:0,T:0,W:0,I:0,A:0,Ld:0,Cl:0,Wil:0,Int:0};const factions=['House Escher','House Goliath','House Orlock','House Van Saar','House Cawdor','House Delaque','Corpse Grinder Cults','Genestealer Cult','Helot Cult','Enforcers','Venators','Outcasts','Squats','Nomads','Spyrers','Custom'];
function demo(){return {gangs:[],campaigns:[],edition:'N26',view:'dashboard',selectedGang:null,selectedCampaign:null,tab:'fighters'};}let data;try{data=JSON.parse(localStorage.getItem(KEY))||demo()}catch{data=demo()}let modalOpen=false,menuOpen=false,query='';function save(){localStorage.setItem(KEY,JSON.stringify(data));render()}function log(g,t){g.logs??=[];g.logs.unshift({id:id(),at:now(),text:t});}function gang(){return data.gangs.find(x=>x.id===data.selectedGang)}function campaign(){return data.campaigns.find(x=>x.id===data.selectedCampaign)}function rating(g){return (g?.fighters||[]).filter(f=>f.status!=='Dead').reduce((a,f)=>a+n(f.ratingCost??f.cost)+(f.equipment||[]).reduce((b,e)=>b+n(e.cost),0),0)+(g?.stash||[]).reduce((a,e)=>a+n(e.cost),0)}function date(x){return new Date(x).toLocaleString('ko-KR',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}function chip(t,cl=''){return `<span class="chip ${cl}">${esc(t)}</span>`}function btn(label,action,kind=''){return `<button class="btn ${kind}" data-action="${action}">${label}</button>`}function heading(k,t,sub,actions=''){return `<div class="heading"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}function empty(sym,title,sub,action=''){return `<div class="empty"><div class="symbol">${sym}</div><h3>${title}</h3><p>${sub}</p>${action}</div>`}function stat(label,value,sub=''){return `<div class="stat"><div class="label">${label}</div><div class="value">${value}</div><div class="sub">${sub}</div></div>`}function render(){const nav=[['dashboard','▦','대시보드'],['gangs','⚔','갱'],['campaigns','◈','캠페인'],['settings','⚙','데이터 관리']];$('#app').innerHTML=`<div class="app"><aside class="sidebar ${menuOpen?'open':''}"><div class="logo"><div class="sigil">U</div><div class="brand">언더하이브 코리아<small>갱 · 캠페인 매니저</small></div></div><div><div class="nav-label">WORKSPACE</div><div class="nav">${nav.map(([v,i,t])=>`<button data-nav="${v}" class="${data.view===v||data.view==='gang'&&v==='gangs'||data.view==='campaign'&&v==='campaigns'?'active':''}"><span class="ico">${i}</span>${t}</button>`).join('')}</div></div><div class="side-foot">갱과 캠페인의 기록을 한곳에.<br>데이터는 이 브라우저에 저장됩니다.</div></aside><main class="main"><div class="topbar"><div class="top-wordmark"><span class="top-emblem"><img width="36" height="36" alt="" src="/brand/underhive-korea-192.png"></span><span>언더하이브 코리아</span></div><div class="top-actions"><button class="icon-btn" data-action="menu" aria-label="메뉴">☰</button></div></div><div class="crumb"><span>⌂</span> / <strong>${esc(({dashboard:'홈',gangs:'갱',gang:gang()?.name||'갱 상세',campaigns:'캠페인',campaign:'캠페인 상세',settings:'데이터 관리'})[data.view])}</strong></div><div class="content">${({dashboard:dashboard,gangs:gangsPage,gang:gangPage,campaigns:campaignsPage,campaign:campaignPage,settings:settingsPage})[data.view]?.()||dashboard()}</div></main></div>`}function dashboard(){const fighters=data.gangs.flatMap(g=>g.fighters||[]),battles=data.campaigns.flatMap(c=>c.battles||[]);return heading('COMMAND CENTER','대시보드','언더하이브의 모든 기록을 한눈에 확인하세요.',btn('＋ 캠페인 만들기','new-campaign'))+`<div class="stats">${stat('운영 중인 갱',data.gangs.length,'나의 갱')}${stat('파이터',fighters.length,`${fighters.filter(f=>f.status==='Active').length}명 활동 중`)}${stat('총 갱 평점',fmt(data.gangs.reduce((a,g)=>a+rating(g),0)),'크레딧 상당')}${stat('기록된 전투',battles.length,'모든 캠페인')}</div><div class="split"><section><h2 class="section-title">나의 갱 ${btn('전체 보기','nav-gangs','small ghost')}</h2>${data.gangs.length?`<div class="grid">${data.gangs.slice(0,6).map(g=>gangCard(g)).join('')}</div>`:empty('⚔','아직 갱이 없습니다','새 갱을 만들어 명단을 관리해 보세요.',btn('갱 만들기','new-gang','primary'))}<h2 class="section-title" style="margin-top:26px">캠페인 ${btn('전체 보기','nav-campaigns','small ghost')}</h2>${data.campaigns.length?`<div class="grid">${data.campaigns.slice(0,3).map(c=>campaignCard(c)).join('')}</div>`:empty('◈','캠페인이 없습니다','캠페인을 만들고 갱을 등록하세요.',btn('캠페인 만들기','new-campaign','primary'))}</section><aside class="stack"><div class="card"><h3>빠른 시작</h3><p>갱 → 파이터 → 캠페인 순으로 등록하세요.</p><div class="mini-list">${btn('갱 만들기','new-gang')}${btn('캠페인 만들기','new-campaign')}${btn('JSON 백업','export')}</div></div><div class="card"><h3>최근 활동</h3>${data.gangs.flatMap(g=>(g.logs||[]).map(l=>({...l,gang:g.name}))).sort((a,b)=>b.at.localeCompare(a.at)).slice(0,5).map(l=>`<div class="log"><time>${date(l.at)} · ${esc(l.gang)}</time><b>${esc(l.text)}</b></div>`).join('')||'<p>기록이 없습니다.</p>'}</div></aside></div>`}function gangCard(g){return `<article class="card"><div>${chip(g.faction)} ${chip(g.edition,'gold')}</div><h3>${esc(g.name)}</h3><p>${esc(g.notes||'갱의 이야기를 기록하세요.')}</p><div class="meta"><span><b>${fmt(rating(g))}</b>갱 평점</span><span><b>${(g.fighters||[]).length}</b>파이터</span><span><b>${fmt(g.credits)}</b>크레딧</span></div><div class="card-actions"><button class="btn small primary" data-open-gang="${g.id}">갱 열기</button><button class="btn small" data-edit-gang="${g.id}">수정</button></div></article>`}function gangsPage(){return heading('GANG ROSTER','나의 갱','갱 자원, 파이터, 무기와 이력을 관리하세요.',btn('＋ 새 갱','new-gang','primary'))+(data.gangs.length?`<div class="grid">${data.gangs.map(gangCard).join('')}</div>`:empty('⚔','갱이 없습니다','첫 갱을 만들어 시작하세요.',btn('갱 만들기','new-gang','primary')))}function gangPage(){const g=gang();if(!g)return gangsPage();const tabs=[['fighters','파이터'],['stash','장비 창고'],['resources','자원'],['logs','활동 기록']];return heading('GANG DOSSIER',esc(g.name),`${esc(g.faction)} · ${esc(g.edition)} · ${esc(g.alignment)}`,btn('갱 수정','edit-current-gang')+btn('삭제','delete-gang','danger'))+`<div class="stats">${stat('갱 평점',fmt(rating(g)),'파이터 + 장비')}${stat('크레딧',fmt(g.credits),'사용 가능')}${stat('명성',fmt(g.reputation),'Reputation')}${stat('파이터',g.fighters.length,`${g.fighters.filter(f=>f.status==='Active').length}명 활동 중`)}</div><div class="tabs">${tabs.map(([v,t])=>`<button data-tab="${v}" class="${data.tab===v?'active':''}">${t}</button>`).join('')}</div>${({fighters:()=>fightersTab(g),stash:()=>stashTab(g),resources:()=>resourcesTab(g),logs:()=>logsTab(g)})[data.tab]?.()||fightersTab(g)}`}function fightersTab(g){const fs=g.fighters.filter(f=>`${f.name} ${f.type}`.toLowerCase().includes(query.toLowerCase()));return `<div class="toolbar"><h2 class="section-title">파이터 명단 (${g.fighters.length})</h2><div class="actions"><input class="field search" id="fighter-search" placeholder="이름 또는 유형 검색" value="${esc(query)}">${btn('＋ 파이터','new-fighter','primary')}</div></div>${g.fighters.length?`<div class="table-wrap"><table><thead><tr><th>이름 / 유형</th><th>상태</th><th>능력치</th><th>경험치</th><th>장비</th><th>비용</th><th></th></tr></thead><tbody>${fs.map(f=>`<tr><td><span class="name">${esc(f.name)}</span><br><span class="muted">${esc(f.type)}</span></td><td>${chip(f.status,f.status==='Active'?'':'red')}</td><td>M ${f.stats.M} · WS ${f.stats.WS}+ · BS ${f.stats.BS}+ · W ${f.stats.W}</td><td>${fmt(f.xp)} XP</td><td>${f.equipment.length}개</td><td class="gold">${fmt(f.cost)} cr</td><td><button class="btn small" data-fighter="${f.id}">상세</button></td></tr>`).join('')}</tbody></table></div>`:empty('◇','파이터가 없습니다','파이터를 추가해 명단을 구성하세요.',btn('파이터 추가','new-fighter','primary'))}`}function stashTab(g){return `<div class="toolbar"><h2 class="section-title">갱 장비 창고</h2>${btn('＋ 장비 등록','new-stash','primary')}</div>${g.stash.length?`<div class="table-wrap"><table><thead><tr><th>장비</th><th>가치</th><th>관리</th></tr></thead><tbody>${g.stash.map(e=>`<tr><td class="name">${esc(e.name)}</td><td>${fmt(e.cost)} cr</td><td class="table-actions"><button class="btn small" data-stash-assign="${e.id}">파이터에게 지급</button><button class="btn small danger" data-stash-remove="${e.id}">삭제</button></td></tr>`).join('')}</tbody></table></div>`:empty('□','장비 창고가 비었습니다','예비 무기나 장비를 등록하세요.')}<p class="footer-note">창고 장비는 갱 평점에 포함됩니다.</p>`}function resourcesTab(g){return `<div class="split"><div class="stack"><div class="card"><h3>갱 자원</h3><div class="mini-list">${[['credits','크레딧'],['reputation','명성'],['meat','고기'],['exploration','탐사 포인트']].map(([k,t])=>`<div class="mini-row"><span>${t}</span><strong class="gold">${fmt(g[k])}</strong><button class="btn small" data-resource="${k}">조정</button></div>`).join('')}</div></div><div class="card"><h3>갱 정보</h3><p>${esc(g.notes||'메모 없음')}</p><div class="mini-row">성향 <strong>${esc(g.alignment)}</strong></div><div class="mini-row">에디션 <strong>${esc(g.edition)}</strong></div></div></div><div class="card"><h3>평점 구성</h3><p>파이터와 장비의 비용 합계입니다.</p><div class="mini-row">파이터 ${fmt(g.fighters.reduce((a,f)=>a+n(f.cost),0))} cr</div><div class="mini-row">파이터 장비 ${fmt(g.fighters.flatMap(f=>f.equipment).reduce((a,e)=>a+n(e.cost),0))} cr</div><div class="mini-row">창고 ${fmt(g.stash.reduce((a,e)=>a+n(e.cost),0))} cr</div><div class="mini-row"><strong>총 평점</strong><strong class="gold">${fmt(rating(g))}</strong></div></div></div>`}function logsTab(g){return `<div class="toolbar"><h2 class="section-title">활동 기록</h2>${btn('＋ 메모','new-log')}</div><div class="card">${g.logs.length?g.logs.map(l=>`<div class="log"><time>${date(l.at)}</time><b>${esc(l.text)}</b></div>`).join(''):'기록이 없습니다.'}</div>`}function campaignCard(c){return `<article class="card">${chip(c.phase,'gold')} ${chip(c.edition)}<h3>${esc(c.name)}</h3><p>${esc(c.description||'캠페인 기록')}</p><div class="meta"><span><b>${c.members.length}</b>참가 갱</span><span><b>${c.territories.length}</b>영토</span><span><b>${c.battles.length}</b>전투</span></div><button class="btn small primary" data-open-campaign="${c.id}">캠페인 열기</button></article>`}function campaignsPage(){return heading('CAMPAIGNS','캠페인','플레이어, 갱, 영토와 전투를 기록하세요.',btn('＋ 새 캠페인','new-campaign','primary'))+(data.campaigns.length?`<div class="grid">${data.campaigns.map(campaignCard).join('')}</div>`:empty('◈','캠페인이 없습니다','새 캠페인을 만들어 보세요.',btn('캠페인 만들기','new-campaign','primary')))}function campaignPage(){const c=campaign();if(!c)return campaignsPage();const tabs=[['members','갱과 플레이어'],['territories','영토'],['battles','전투 기록'],['overview','개요']];const ct=tabs.some(([key])=>key===data.campaignTab)?data.campaignTab:'members';return heading('CAMPAIGN RECORD',esc(c.name),`${esc(c.edition)} · ${esc(c.phase)}`,btn('캠페인 수정','edit-campaign')+btn('삭제','delete-campaign','danger'))+`<div class="stats">${stat('참가 갱',c.members.length,'플레이어 지정')}${stat('영토',c.territories.length,'등록된 영토')}${stat('전투',c.battles.length,'기록된 전투')}${stat('최고 평점',fmt(Math.max(0,...c.members.map(m=>rating(data.gangs.find(g=>g.id===m.gangId))))),'참가 갱 기준')}</div><div class="tabs">${tabs.map(([v,t])=>`<button data-campaign-tab="${v}" class="${ct===v?'active':''}">${t}</button>`).join('')}</div>${({members:()=>membersTab(c),territories:()=>territoriesTab(c),battles:()=>battlesTab(c),overview:()=>overviewTab(c)})[ct]()}`}function membersTab(c){return `<div class="toolbar"><h2 class="section-title">참가 갱과 플레이어</h2>${btn('＋ 참가자','new-member','primary')}</div>${c.members.length?`<div class="table-wrap"><table><thead><tr><th>플레이어</th><th>갱</th><th>역할</th><th>평점</th><th></th></tr></thead><tbody>${c.members.map(m=>{let g=data.gangs.find(x=>x.id===m.gangId);return `<tr><td class="name">${esc(m.player)}</td><td>${esc(g?.name||'삭제된 갱')}</td><td>${chip(m.role)}</td><td>${fmt(rating(g))}</td><td class="table-actions"><button class="btn small" data-member-role="${m.id}">역할</button><button class="btn small danger" data-member-remove="${m.id}">제거</button></td></tr>`}).join('')}</tbody></table></div>`:empty('♟','참가자가 없습니다','플레이어와 갱을 캠페인에 추가하세요.',btn('참가자 추가','new-member','primary'))}`}function territoriesTab(c){return `<div class="toolbar"><h2 class="section-title">영토</h2>${btn('＋ 영토','new-territory','primary')}</div>${c.territories.length?`<div class="grid">${c.territories.map(t=>`<div class="card">${chip(data.gangs.find(g=>g.id===t.gangId)?.name||'중립')}<h3>${esc(t.name)}</h3><p>${esc(t.notes||'메모 없음')}</p><div class="actions"><button class="btn small" data-territory-edit="${t.id}">수정 / 소유권</button><button class="btn small danger" data-territory-remove="${t.id}">삭제</button></div></div>`).join('')}</div>`:empty('⬡','영토가 없습니다','캠페인 영토를 등록하세요.',btn('영토 추가','new-territory','primary'))}`}function battlesTab(c){return `<div class="toolbar"><h2 class="section-title">전투 기록</h2>${btn('＋ 전투','new-battle','primary')}</div>${c.battles.length?`<div class="table-wrap"><table><thead><tr><th>날짜</th><th>전투 / 시나리오</th><th>승자</th><th>메모</th><th></th></tr></thead><tbody>${[...c.battles].sort((a,b)=>b.date.localeCompare(a.date)).map(b=>`<tr><td>${esc(b.date)}</td><td class="name">${esc(b.name)}</td><td>${esc(data.gangs.find(g=>g.id===b.winner)?.name||'무승부')}</td><td>${esc(b.notes)}</td><td><button class="btn small danger" data-battle-remove="${b.id}">삭제</button></td></tr>`).join('')}</tbody></table></div>`:empty('⚔','전투 기록이 없습니다','첫 전투를 기록하세요.',btn('전투 기록','new-battle','primary'))}`}function overviewTab(c){return `<div class="split"><div class="card"><h3>캠페인 정보</h3><p>${esc(c.description||'설명 없음')}</p><div class="mini-row">에디션 <strong>${esc(c.edition)}</strong></div><div class="mini-row">상태 <strong>${esc(c.phase)}</strong></div><h3>메모</h3><p>${esc(c.notes||'메모 없음')}</p></div><div class="card"><h3>갱 평점 순위</h3><div class="mini-list">${[...c.members].sort((a,b)=>rating(data.gangs.find(g=>g.id===b.gangId))-rating(data.gangs.find(g=>g.id===a.gangId))).map((m,i)=>`<div class="mini-row"><span>${i+1}. ${esc(data.gangs.find(g=>g.id===m.gangId)?.name||'삭제된 갱')}</span><strong>${fmt(rating(data.gangs.find(g=>g.id===m.gangId)))}</strong></div>`).join('')||'<p>참가 갱이 없습니다.</p>'}</div></div></div>`}function settingsPage(){return heading('ARCHIVE','데이터 관리','기록을 백업하고 다른 브라우저로 옮기세요.')+`<div class="notice"><strong>저장 위치</strong> · 데이터는 현재 브라우저에만 저장됩니다. 기기를 바꾸거나 브라우저 데이터를 삭제하기 전 JSON으로 백업하세요.</div><div class="grid"><div class="card"><h3>JSON 내보내기</h3><p>갱, 파이터, 캠페인, 영토와 전투를 한 파일로 저장합니다.</p>${btn('백업 다운로드','export','primary')}</div><div class="card"><h3>JSON 가져오기</h3><p>이 앱에서 내보낸 백업 파일로 현재 데이터를 교체합니다.</p>${btn('백업 가져오기','import')}</div><div class="card"><h3>예시 데이터</h3><p>앱을 처음 연 상태로 되돌립니다.</p>${btn('예시로 초기화','reset','danger')}</div></div><p class="footer-note">이 앱은 독립 제작한 팬 도구입니다. Munda Manager와 별도로 갱과 캠페인을 저장하는 팬 도구입니다.</p>`}
function formModal(title,fields,onSubmit,submit='저장'){const html=`<form id="modal-form" class="form two">${fields}</form>`;showModal(title,html,submit,()=>{const f=$('#modal-form');if(!f.reportValidity())return false;let values=Object.fromEntries(new FormData(f));return onSubmit(values)!==false})}function field(name,label,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}function select(name,label,options,value){return `<label>${label}<select name="${name}">${options.map(o=>{let [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`}function textarea(name,label,value=''){return `<label class="wide">${label}<textarea name="${name}">${esc(value)}</textarea></label>`}function showModal(title,body,submit,onSubmit){modalOpen=true;document.body.insertAdjacentHTML('beforeend',`<div class="modal-bg"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="icon-btn" id="modal-close" aria-label="닫기">×</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button class="btn" id="modal-cancel">취소</button><button class="btn primary" id="modal-submit">${submit}</button></div></div></div>`);$('#modal-close').onclick=$('#modal-cancel').onclick=closeModal;$('#modal-submit').onclick=()=>{if(onSubmit()!==false)closeModal()};$('#modal-form')?.addEventListener('submit',e=>{e.preventDefault();$('#modal-submit').click()})}function closeModal(){document.querySelector('.modal-bg')?.remove();modalOpen=false}function confirmDelete(title,body,fn){showModal(title,`<p>${body}</p>`,'삭제',()=>{fn();return true})}
function editGang(g){formModal(g?'갱 수정':'새 갱 만들기',field('name','갱 이름',g?.name,'text','required')+select('faction','세력',factions,g?.faction)+select('edition','에디션',['N23','N26','Custom'],g?.edition||'N23')+select('alignment','성향',['Law Abiding','Outlaw','Neutral'],g?.alignment||'Law Abiding')+field('credits','크레딧',g?.credits??'','number','min="0"')+field('reputation','명성',g?.reputation??0,'number','min="0"')+textarea('notes','갱 메모',g?.notes),v=>{if(g){Object.assign(g,{name:v.name,faction:v.faction,edition:v.edition,alignment:v.alignment,credits:n(v.credits),reputation:n(v.reputation),notes:v.notes});log(g,'갱 정보를 수정했습니다.')}else{g={id:id(),name:v.name,faction:v.faction,edition:v.edition,alignment:v.alignment,credits:n(v.credits),reputation:n(v.reputation),meat:0,exploration:0,notes:v.notes,stash:[],fighters:[],logs:[]};data.gangs.push(g);data.selectedGang=g.id;data.view='gang';data.tab='fighters';log(g,'갱을 만들었습니다.')}save()})}function editFighter(f){const g=gang();formModal(f?'파이터 수정':'파이터 추가',field('name','이름',f?.name,'text','required')+field('type','유형 / 계급',f?.type||'Ganger','text','required')+field('cost','기본 비용 (cr)',f?.cost??0,'number','min="0"')+select('status','상태',['Active','In Recovery','Captured','Retired','Dead','Enslaved','Starved'],f?.status||'Active')+field('xp','경험치',f?.xp??0,'number','min="0"')+field('kills','처치 수',f?.kills??0,'number','min="0"')+textarea('notes','메모',f?.notes),v=>{if(f){Object.assign(f,{name:v.name,type:v.type,cost:n(v.cost),status:v.status,xp:n(v.xp),kills:n(v.kills),notes:v.notes});log(g,`${f.name}의 정보를 수정했습니다.`)}else{f={id:id(),name:v.name,type:v.type,cost:n(v.cost),status:v.status,xp:n(v.xp),kills:n(v.kills),stats:{...baseStats},equipment:[],skills:[],effects:[],notes:v.notes};g.fighters.push(f);log(g,`${f.name} 파이터를 추가했습니다.`)}save()})}function fighterDetail(f){const g=gang();const adjusted={...f.stats};(f.effects||[]).forEach(e=>{if(adjusted[e.stat]!=null)adjusted[e.stat]+=Number(e.amount)});const stats=Object.entries(adjusted).map(([k,v])=>`<div class="mini-row"><span>${k}</span><strong>${v}${['WS','BS','I'].includes(k)?'+':''}</strong></div>`).join('');showModal(esc(f.name),`<p>${chip(f.type)} ${chip(f.status,f.status==='Active'?'':'red')} · ${fmt(f.xp)} XP · ${fmt(f.kills)} 처치</p><div class="mini-list" style="grid-template-columns:repeat(3,1fr)">${stats}</div><h3>장비</h3><div class="mini-list">${f.equipment.map(e=>`<div class="mini-row">${esc(e.name)} · ${fmt(e.cost)} cr <span><button class="btn small" data-to-stash="${f.id}:${e.id}">창고로</button><button class="btn small danger" data-equipment-remove="${f.id}:${e.id}">삭제</button></span></div>`).join('')||'<p class="muted">장비 없음</p>'}</div><div class="actions" style="margin-top:10px"><button class="btn small" data-add-equipment="${f.id}">＋ 장비</button><button class="btn small" data-add-skill="${f.id}">＋ 스킬</button><button class="btn small" data-add-effect="${f.id}">＋ 효과/부상</button></div><h3>스킬 / 특성</h3><p>${f.skills.map(esc).join(' · ')||'없음'}</p><h3>효과 / 부상</h3><p>${f.effects.map(e=>`${esc(e.name)} (${esc(e.stat)} ${e.amount>0?'+':''}${e.amount})`).join(' · ')||'없음'}</p><p class="muted">${esc(f.notes||'메모 없음')}</p><div class="actions"><button class="btn" data-edit-fighter="${f.id}">기본 정보 수정</button><button class="btn" data-stats="${f.id}">능력치 수정</button><button class="btn danger" data-delete-fighter="${f.id}">파이터 삭제</button></div>`,'닫기',()=>true)}function editStats(f){formModal(`${esc(f.name)} · 능력치`,Object.entries(f.stats).map(([k,v])=>field(k,k,v,'number','required')).join(''),v=>{Object.keys(f.stats).forEach(k=>f.stats[k]=Number(v[k]));log(gang(),`${f.name}의 능력치를 수정했습니다.`);save()})}function addEquipment(f,stash=false){const g=gang();formModal('장비 등록',field('name','장비 이름','','text','required')+field('cost','비용 (cr)',0,'number','min="0"')+select('destination','보관 위치',[['fighter','파이터'],['stash','갱 창고']],stash?'stash':'fighter')+`<label class="wide"><input type="checkbox" name="spend" value="yes" style="width:auto"> 갱 크레딧에서 비용 차감</label>`,v=>{let e={id:id(),name:v.name,cost:n(v.cost)};if(v.destination==='stash'||!f)g.stash.push(e);else f.equipment.push(e);if(v.spend==='yes')g.credits=Math.max(0,g.credits-e.cost);log(g,`${e.name} 장비를 등록했습니다.`);save()})}function editCampaign(c){formModal(c?'캠페인 수정':'새 캠페인 만들기',field('name','캠페인 이름',c?.name,'text','required')+select('edition','에디션',['N23','N26','Custom'],c?.edition||'N23')+select('phase','상태',['준비 중','진행 중','종료'],c?.phase||'준비 중')+textarea('description','설명',c?.description)+textarea('notes','메모',c?.notes),v=>{if(c)Object.assign(c,v);else{c={id:id(),...v,members:[],territories:[],battles:[]};data.campaigns.push(c);data.selectedCampaign=c.id;data.view='campaign'}save()})}function gangOptions(selected='',neutral=false){return (neutral?[["",'중립 / 없음']]:[]).concat(data.gangs.map(g=>[g.id,g.name]))}function editTerritory(t){let c=campaign();formModal(t?'영토 수정':'영토 추가',field('name','영토 이름',t?.name,'text','required')+select('gangId','소유 갱',gangOptions('',true),t?.gangId||'')+textarea('notes','메모',t?.notes),v=>{if(t)Object.assign(t,v);else c.territories.push({id:id(),...v});save()})}function newMember(){if(!data.gangs.length){alert('먼저 갱을 만드세요.');return}let c=campaign();formModal('참가자 추가',field('player','플레이어 이름','','text','required')+select('gangId','갱',gangOptions())+select('role','역할',['Player','Arbitrator'], 'Player'),v=>{c.members.push({id:id(),...v});save()})}function newBattle(){let c=campaign();formModal('전투 기록',field('name','시나리오 / 전투 이름','','text','required')+field('date','날짜',new Date().toISOString().slice(0,10),'date','required')+select('winner','승리 갱',gangOptions('',true))+textarea('notes','결과 메모'),v=>{c.battles.push({id:id(),...v});save()})}function exportData(){let exportState=data;let a=document.createElement('a'),blob=new Blob([JSON.stringify({version:1,exportedAt:now(),data:exportState},null,2)],{type:'application/json'});a.href=URL.createObjectURL(blob);a.download='underhive-ledger-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function act(action,target){const g=gang(),c=campaign();if(action==='menu'){menuOpen=!menuOpen;render()}else if(action==='new-gang')editGang();else if(action==='edit-current-gang')editGang(g);else if(action==='delete-gang')confirmDelete('갱 삭제',`${esc(g.name)}과 모든 파이터·장비를 삭제할까요?`,()=>{data.gangs=data.gangs.filter(x=>x.id!==g.id);data.view='gangs';save()});else if(action==='new-fighter')editFighter();else if(action==='new-stash')addEquipment(null,true);else if(action==='new-log')formModal('활동 메모',textarea('text','메모 내용'),v=>{if(v.text.trim()){log(g,v.text.trim());save()}});else if(action==='new-campaign')editCampaign();else if(action==='edit-campaign')editCampaign(c);else if(action==='delete-campaign')window.UKDeleteCampaign(c);else if(action==='new-member')newMember();else if(action==='new-territory')editTerritory();else if(action==='new-battle')newBattle();else if(action==='export')exportData();else if(action==='import')$('#import-file').click();else if(action==='reset')confirmDelete('초기화','모든 현재 데이터를 예시 데이터로 바꿀까요?',()=>{data=demo();save()});else if(action==='nav-gangs'){data.view='gangs';save()}else if(action==='nav-campaigns'){data.view='campaigns';save()}}
document.addEventListener('click',e=>{let t=e.target.closest('[data-action],[data-nav],[data-tab],[data-campaign-tab],[data-open-gang],[data-edit-gang],[data-open-campaign],[data-fighter],[data-edit-fighter],[data-delete-fighter],[data-stats],[data-resource],[data-stash-assign],[data-stash-remove],[data-add-equipment],[data-add-skill],[data-add-effect],[data-to-stash],[data-equipment-remove],[data-member-role],[data-member-remove],[data-territory-edit],[data-territory-remove],[data-battle-remove]');if(!t)return;const d=t.dataset;let g=gang(),c=campaign();if(d.action){act(d.action,t);return}if(d.nav){data.view=d.nav;menuOpen=false;save()}else if(d.tab){data.tab=d.tab;save()}else if(d.campaignTab){data.campaignTab=d.campaignTab;save()}else if(d.openGang){data.selectedGang=d.openGang;data.view='gang';data.tab='fighters';query='';save()}else if(d.editGang)editGang(data.gangs.find(g=>g.id===d.editGang));else if(d.openCampaign){data.selectedCampaign=d.openCampaign;data.view='campaign';data.campaignTab='members';save()}else if(d.fighter)fighterDetail(g.fighters.find(f=>f.id===d.fighter));else if(d.editFighter){closeModal();editFighter(g.fighters.find(f=>f.id===d.editFighter))}else if(d.deleteFighter){let f=g.fighters.find(x=>x.id===d.deleteFighter);closeModal();confirmDelete('파이터 삭제',`${esc(f.name)}을(를) 삭제할까요?`,()=>{g.fighters=g.fighters.filter(x=>x.id!==f.id);log(g,`${f.name} 파이터를 삭제했습니다.`);save()})}else if(d.stats){closeModal();editStats(g.fighters.find(f=>f.id===d.stats))}else if(d.resource){let labels={credits:'크레딧',reputation:'명성',meat:'고기',exploration:'탐사 포인트'},k=d.resource;formModal(`${labels[k]} 조정`,field('value','새 값',g[k],'number','min="0" required'),v=>{let old=g[k];g[k]=n(v.value);log(g,`${labels[k]}: ${old} → ${g[k]}`);save()})}else if(d.stashAssign){let e=g.stash.find(x=>x.id===d.stashAssign);if(!g.fighters.length){alert('먼저 파이터를 추가하세요.');return}formModal('장비 지급',select('fighter','받을 파이터',g.fighters.map(f=>[f.id,f.name])),v=>{g.fighters.find(f=>f.id===v.fighter).equipment.push(e);g.stash=g.stash.filter(x=>x.id!==e.id);log(g,`${e.name}을(를) 파이터에게 지급했습니다.`);save()})}else if(d.stashRemove){let x=g.stash.find(e=>e.id===d.stashRemove);confirmDelete('장비 삭제',`${esc(x.name)}을(를) 창고에서 삭제할까요?`,()=>{g.stash=g.stash.filter(e=>e.id!==x.id);log(g,`${x.name} 장비를 삭제했습니다.`);save()})}else if(d.addEquipment){closeModal();addEquipment(g.fighters.find(f=>f.id===d.addEquipment))}else if(d.addSkill){closeModal();let f=g.fighters.find(x=>x.id===d.addSkill);formModal('스킬 추가',field('name','스킬 이름','','text','required'),v=>{f.skills.push(v.name);log(g,`${f.name}에게 ${v.name} 스킬을 추가했습니다.`);save()})}else if(d.addEffect){closeModal();let f=g.fighters.find(x=>x.id===d.addEffect);formModal('효과 / 부상 추가',field('name','이름','','text','required')+select('category','분류',['Injury','Advancement','Bionic','Equipment','Skill','User'])+select('stat','변경 능력치',Object.keys(baseStats))+field('amount','수치 변화',0,'number','required'),v=>{f.effects.push({id:id(),name:v.name,category:v.category,stat:v.stat,amount:Number(v.amount)});log(g,`${f.name}에게 ${v.name} 효과를 추가했습니다.`);save()})}else if(d.toStash){let [fid,eid]=d.toStash.split(':'),f=g.fighters.find(x=>x.id===fid),x=f.equipment.find(e=>e.id===eid);g.stash.push(x);f.equipment=f.equipment.filter(e=>e.id!==eid);closeModal();log(g,`${x.name}을(를) 창고로 이동했습니다.`);save()}else if(d.equipmentRemove){let [fid,eid]=d.equipmentRemove.split(':'),f=g.fighters.find(x=>x.id===fid),x=f.equipment.find(e=>e.id===eid);f.equipment=f.equipment.filter(e=>e.id!==eid);closeModal();log(g,`${x.name} 장비를 삭제했습니다.`);save()}else if(d.memberRole){let m=c.members.find(x=>x.id===d.memberRole);formModal('플레이어 역할 변경',select('role','역할',['Player','Arbitrator'],m.role),v=>{m.role=v.role;save()})}else if(d.memberRemove)confirmDelete('참가자 제거','캠페인에서 이 참가자를 제거할까요?',()=>{c.members=c.members.filter(x=>x.id!==d.memberRemove);save()});else if(d.territoryEdit)editTerritory(c.territories.find(x=>x.id===d.territoryEdit));else if(d.territoryRemove)confirmDelete('영토 삭제','이 영토를 삭제할까요?',()=>{c.territories=c.territories.filter(x=>x.id!==d.territoryRemove);save()});else if(d.battleRemove)confirmDelete('전투 삭제','이 전투 기록을 삭제할까요?',()=>{c.battles=c.battles.filter(x=>x.id!==d.battleRemove);save()})});document.addEventListener('input',e=>{if(e.target.id==='fighter-search'){query=e.target.value;let pos=e.target.selectionStart;render();let el=$('#fighter-search');el?.focus();el?.setSelectionRange(pos,pos)}});render();
